# Mid-June, mid-morning UTC: far from any month/DST edge, and every dataset
# below is built relative to it so day bucketing is fully deterministic.
FROZEN_NOW = datetime(2026, 6, 15, 11, 0, tzinfo=UTC)


class _FrozenDatetime(datetime):
    """datetime subclass with a pinned now(); everything else inherited."""

    @classmethod
    def now(cls, tz=None):  # type: ignore[override]
        if tz is None:
            return FROZEN_NOW.replace(tzinfo=None)
        return FROZEN_NOW.astimezone(tz)


@pytest.fixture(autouse=True)
def _frozen_clock(monkeypatch: pytest.MonkeyPatch) -> None:
    """Pin the module clock of every module that branches on ``now()``."""
    monkeypatch.setattr("src.domains.health_metrics.service.datetime", _FrozenDatetime)
    monkeypatch.setattr("src.domains.health_metrics.signals.datetime", _FrozenDatetime)


class _FakeSampleRepo:
    """In-memory stand-in for ``HealthSampleRepository``.

    Serves the raw-sample and the per-day-rollup interfaces from ONE dataset,
    so the golden net is blind to which one the service calls.
    """

    def __init__(self, samples: list[HealthSample]) -> None:
        self._samples = samples

    def _window(self, kind: str, from_ts: datetime, to_ts: datetime) -> list[HealthSample]:
        return [s for s in self._samples if s.kind == kind and from_ts <= s.date_start < to_ts]

    async def fetch_samples_kind(
        self, user_id: UUID, *, kind: str, from_ts: datetime, to_ts: datetime
    ) -> list[HealthSample]:
        return self._window(kind, from_ts, to_ts)

    async def fetch_daily_stats(
        self, user_id: UUID, *, kind: str, from_ts: datetime, to_ts: datetime
    ) -> list[DailyStat]:
        return daily_stats_from_samples(self._window(kind, from_ts, to_ts))


def _make_samples(kind: str, day_values: list[tuple[int, list[int]]]) -> list[HealthSample]:
    """Build samples at ``FROZEN_NOW - days_ago``, noon UTC, one per minute."""
    out: list[HealthSample] = []
    for days_ago, values in day_values:
        base = (FROZEN_NOW - timedelta(days=days_ago)).replace(
            hour=12, minute=0, second=0, microsecond=0
        )
        for index, value in enumerate(values):
            ts = base + timedelta(minutes=index)
            out.append(
                HealthSample(
                    user_id=USER_ID,
                    kind=kind,
                    date_start=ts,
                    date_end=ts + timedelta(minutes=1),
                    value=value,
                    source="test",
                )
            )
    out.sort(key=lambda s: s.date_start)
    return out


