# =============================================================================
# The net
# =============================================================================


def _service_with(samples: list[HealthSample]) -> HealthMetricsService:
    service = HealthMetricsService(MagicMock())
    service.sample_repo = _FakeSampleRepo(samples)  # type: ignore[assignment]
    return service


@pytest.mark.parametrize(
    "case_name,kind,day_values",
    CASES,
    ids=[case[0] for case in CASES],
)
@pytest.mark.parametrize("window_days", WINDOW_DAYS)
async def test_baseline_and_variations_are_pinned(
    case_name: str,
    kind: str,
    day_values: list[tuple[int, list[int]]],
    window_days: int,
) -> None:
    """Service output must be byte-identical to the pre-conversion golden."""
    service = _service_with(_make_samples(kind, day_values))

    delta = await service.compute_kind_baseline_delta(USER_ID, kind, window_days=window_days)
    variations = await service.detect_all_variations(USER_ID, window_days=window_days)

    assert repr((delta, variations)) == EXPECTED[f"{case_name}|{window_days}"]


def test_golden_table_covers_every_case_and_window() -> None:
    """Guard the net against silent shrinkage (a dropped case still passes)."""
    assert set(EXPECTED) == {f"{name}|{w}" for name, _, _ in CASES for w in WINDOW_DAYS}
    assert len(EXPECTED) == len(CASES) * len(WINDOW_DAYS)


def test_golden_table_is_not_vacuous() -> None:
    """A net that only pins empty results would survive any regression.

    Asserts the table actually exercises the branches its docstring claims:
    every baseline mode, both trend directions, and the notable-event path.
    """
    blob = "".join(EXPECTED.values())
    for mode in ("'mode': 'empty'", "'mode': 'bootstrap'", "'mode': 'rolling'"):
        assert mode in blob, f"golden table never exercises {mode}"
    assert "'trend': 'rising'" in blob
    assert "'trend': 'falling'" in blob
    assert "'event': 'inactivity_streak'" in blob


@pytest.mark.parametrize("case_name,kind,day_values", CASES, ids=[case[0] for case in CASES])
def test_unrounded_daily_aggregates_are_pinned(
    case_name: str,
    kind: str,
    day_values: list[tuple[int, list[int]]],
) -> None:
    """Pin the aggregation contract BELOW the service payload's rounding.

    ``compute_kind_baseline_delta`` rounds every number to one decimal, so a
    sub-0.05 drift is invisible in the main net (verified by mutation testing:
    rounding the daily average to 1 decimal leaves all 182 entries green).
    The rollup's correctness claim is *bit-exactness*, so it is pinned here,
    on the raw values: per-day aggregates and the unrounded baseline median.
    """
    spec = HEALTH_KINDS[kind]
    samples = _make_samples(kind, day_values)

    daily = _daily_aggregate(samples, spec.baseline_kind)
    baseline = compute_baseline(samples, spec)

    assert (
        repr((daily, (baseline.mode, baseline.median_value, baseline.days_available)))
        == EXPECTED_DAILY[case_name]
    )


@pytest.mark.parametrize("case_name,kind,day_values", CASES, ids=[case[0] for case in CASES])
def test_rollup_matches_in_python_grouping(
    case_name: str,
    kind: str,
    day_values: list[tuple[int, list[int]]],
) -> None:
    """``daily_stats_from_samples`` must reproduce ``_daily_aggregate`` exactly.

    This is the in-memory half of the rollup equivalence; the SQL half (that
    PostgreSQL's per-day ``sum``/``count``/``min`` equals this grouping) is
    pinned by the integration test against a real database.
    """
    spec = HEALTH_KINDS[kind]
    samples = _make_samples(kind, day_values)

    stats = daily_stats_from_samples(samples)
    derived = [_stat_value(stat, spec.baseline_kind) for stat in stats]

    assert derived == _daily_aggregate(samples, spec.baseline_kind)
    assert [stat.day for stat in stats] == sorted(_group_samples_by_day(samples))
    assert all(stat.count >= 1 for stat in stats)
    assert [stat.total for stat in stats] == [
        sum(_group_samples_by_day(samples)[stat.day]) for stat in stats
    ]


@pytest.mark.parametrize(
    "baseline_kind,expected",
    [
        (BaselineKind.DAILY_SUM, 300.0),
        (BaselineKind.DAILY_AVG, 100.0),
        (BaselineKind.RESTING, 60.0),
    ],
)
def test_stat_value_reduces_each_baseline_kind(
    baseline_kind: BaselineKind, expected: float
) -> None:
    """``RESTING`` is unreachable from the registry today, but the branch must
    stay correct for the future kinds its placeholder was written for."""
    stat = DailyStat(day=FROZEN_NOW.date(), total=300, count=3, minimum=60)

    assert _stat_value(stat, baseline_kind) == expected


def test_stat_value_handles_every_baseline_kind() -> None:
    """Completeness guard: a new ``BaselineKind`` without a ``match`` arm would
    fall through and return ``None`` silently, poisoning every downstream
    median. Enum-keyed reductions get an explicit exhaustiveness check (same
    doctrine as the boot-time registry asserts)."""
    stat = DailyStat(day=FROZEN_NOW.date(), total=300, count=3, minimum=60)

    for baseline_kind in BaselineKind:
        assert isinstance(_stat_value(stat, baseline_kind), float), baseline_kind


# =============================================================================
# Explicit coverage the golden table cannot carry (see the fixture-clock note)
# =============================================================================


async def test_single_visible_day_yields_empty_baseline_and_no_variation() -> None:
    """A one-day series: the window swallows it, leaving no baseline.

    ``compute_kind_delta_from_stats`` splits off ``min(window_days, len)`` days
    as the window, so a single day leaves an empty baseline prefix (``mode``
    ``empty``) while still reporting the window value. ``detect_recent_variations``
    then compares the day against itself — a zero delta, never a streak.
    """
    service = _service_with(_make_samples("heart_rate", [(3, [70, 80])]))

    delta = await service.compute_kind_baseline_delta(USER_ID, "heart_rate", window_days=7)
    variations = await service.detect_all_variations(USER_ID, window_days=7)

    assert delta["mode"] == "empty"
    assert delta["window_value"] == 75.0
    assert delta["baseline_value"] is None
    assert delta["delta_pct"] is None
    assert delta["days_available"] == 0
    assert variations == []


async def test_single_visible_day_steps_zero_is_not_an_inactivity_streak() -> None:
    """One zero-step day must not trip the streak (threshold is 3 days)."""
    service = _service_with(_make_samples("steps", [(3, [0])]))

    variations = await service.detect_all_variations(USER_ID, window_days=7)

    assert variations == []


async def test_samples_dated_after_now_are_excluded() -> None:
    """The ``date_start < to_ts`` bound is a contract, not an accident.

    A device clock ahead of the server (or a batch import stamped in the
    future) must not leak into any window — otherwise a single bad sample
    could anchor the baseline.
    """
    service = _service_with(_make_samples("heart_rate", [(0, [200])]))

    delta = await service.compute_kind_baseline_delta(USER_ID, "heart_rate", window_days=7)

    assert delta["mode"] == "empty"
    assert delta["window_value"] is None
